// Why Code: rozbicie maili z Freelancera i Useme na osobne zlecenia (parsowanie tekstu/HTML, żaden node tego nie robi)
// Freelancer: maile po angielsku albo po polsku (od 21.11) - każdy wzorzec łapie oba warianty.
// Useme (od 24.11): w mailu tylko kategoria + tytuł + link, bez budżetu i opisu (strona za Cloudflare - nie czytamy).
const NA_USD = { USD: 1, EUR: 1.08, GBP: 1.27, AUD: 0.65, CAD: 0.73, NZD: 0.6, SGD: 0.74, INR: 0.012, PLN: 0.25 };

function zleceniaFreelancer(tekst) {
  const lista = [];
  const sekcja = tekst.split(/={3,}\s*(?:Projects|Projekty)\s*={3,}/i)[1] || '';
  const bloki = sekcja.split(/\n\s*\n/).map(b => b.trim()).filter(b => /^(?:Budget|Budżet):/im.test(b));
  for (const b of bloki) {
    const budzet = ((b.match(/^(?:Budget|Budżet):\s*(.+)$/im) || [])[1] || '').trim();
    const waluta = (budzet.match(/\b[A-Z]{3}\b/) || ['USD'])[0];
    const kurs = NA_USD[waluta] ?? 0;            // nieznana waluta = 0 -> odpadnie na filtrze budżetu
    const liczby = (budzet.match(/\d[\d,.]*/g) || []).map(n => parseFloat(n.replace(/,/g, '')));
    const maxUsd = Math.round((liczby[1] ?? liczby[0] ?? 0) * kurs);
    const godzinowy = /\/\s*(?:hr|godz)/i.test(budzet);
    const sciezka = (b.match(/^\/projects\/\S+?\.html/m) || [''])[0];
    lista.push({
      alarm: false,
      zrodlo: 'Freelancer',
      tytul: b.split('\n')[0].trim(),
      budzet,
      max_usd: maxUsd,
      godzinowy,
      budzet_ok: godzinowy ? maxUsd >= 10 : maxUsd >= 100,
      umiejetnosci: ((b.match(/^(?:Skills|Umiejętności):\s*(.+)$/im) || [])[1] || '').trim(),
      opis: (b.split(/(?:Description|Opis):\s*/i)[1] || '').split(/\n\/projects\//)[0].replace(/\s+/g, ' ').trim(),
      url: sciezka ? 'https://www.freelancer.com' + sciezka : '',
    });
  }
  return lista;
}

function zleceniaUseme(html) {
  // linki idą przez śledzenie mjt.lu - prawdziwy adres useme.com jest zakodowany (base64) w ostatnim kawałku linku
  const naUseme = (href) => {
    if (/useme\.com\/pl\/jobs\/\d+/.test(href)) return href;
    try { return Buffer.from(href.split('/').pop().split('?')[0], 'base64url').toString('utf8'); } catch (e) { return ''; }
  };
  const czysc = (t) => t.replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#(\d+);/g, (_, n) => String.fromCharCode(n)).trim();
  const lista = [];
  let kategoria = '';
  const wzor = /Kategoria:\s*<a[^>]*>([^<]+)<\/a>|<li[^>]*>\s*<a href="([^"]+)"[^>]*>([^<]+)<\/a>/g;
  for (const m of html.matchAll(wzor)) {
    if (m[1]) { kategoria = czysc(m[1]); continue; }       // nagłówek kategorii - dotyczy zleceń pod nim
    const url = naUseme(m[2]);
    if (!/^https:\/\/useme\.com\/pl\/jobs\/\d+\/?$/.test(url)) continue;  // tylko linki do zleceń
    lista.push({
      alarm: false,
      zrodlo: 'Useme',
      tytul: czysc(m[3]),
      budzet: 'nieznany (Useme nie podaje w mailu)',
      max_usd: 0,
      godzinowy: false,
      budzet_ok: true,                                         // nie znamy budżetu - ocenia Ollama po tytule
      umiejetnosci: kategoria,
      opis: '',
      url,
    });
  }
  return lista;
}

const wyniki = [];
for (const item of $input.all()) {
  const odKogo = JSON.stringify(item.json.from || '').toLowerCase();
  const zrodlo = odKogo.includes('useme') ? 'Useme' : 'Freelancer';
  const zlecenia = zrodlo === 'Useme'
    ? zleceniaUseme(item.json.html || item.json.textAsHtml || '')
    : zleceniaFreelancer(item.json.text || '');
  for (const z of zlecenia) wyniki.push({ json: z });
  if (!zlecenia.length) {  // mail przyszedł, a nie wyciągnęliśmy z niego ani jednego zlecenia
    wyniki.push({ json: { alarm: true, zrodlo, mail_id: item.json.id, temat: item.json.subject || '', data: item.json.date || '' } });
  }
}
return wyniki;

